{"id":"F58","game_id":"otakudle-dragon-ball","series":"dragon-ball","slug":"general-blue","kind":"hint","col":"voice_actor_ja","old_v":"Bin Shimada","new_v":"Toshio Furukawa"}
]$j$;
  c record; r record; cur jsonb; v_empty boolean;
  n_changed integer := 0; n_already integer := 0; n_drift integer := 0; n_missing integer := 0;
begin
  for c in select t.id, t.game_id, t.series, t.slug, t.kind, t.col, nullif(t.old_v, 'null'::jsonb) as old_v, t.new_v
    from jsonb_to_recordset(fixes) as t(id text, game_id text, series text, slug text, kind text, col text, old_v jsonb, new_v jsonb) order by t.id loop
    select f.character_id, f.attrs, f.hints into r
    from public.character_game_facts f
    join public.characters ch on ch.id = f.character_id
    join public.groups g on g.id = ch.group_id and g.site_id = 'anime' and g.slug = c.series
    where ch.slug = c.slug and f.game_id = c.game_id;
    if not found then
      n_missing := n_missing + 1;
      raise warning 'L36 rollback %: no fact row for % / %', c.id, c.game_id, c.slug;
      continue;
    end if;
    cur := case c.kind when 'attr' then r.attrs -> c.col else r.hints -> c.col end;
    if cur is not distinct from c.new_v then
      if c.kind = 'attr' then
        update public.character_game_facts set attrs = jsonb_set(attrs, array[c.col], c.old_v) where character_id = r.character_id and game_id = c.game_id;
      elsif c.old_v is null then
        update public.character_game_facts set hints = hints - c.col where character_id = r.character_id and game_id = c.game_id;
      else
        update public.character_game_facts set hints = jsonb_set(hints, array[c.col], c.old_v) where character_id = r.character_id and game_id = c.game_id;
      end if;
      n_changed := n_changed + 1;
    elsif cur is not distinct from c.old_v or (c.old_v is null and cur is null) then
      n_already := n_already + 1;
    else
      n_drift := n_drift + 1;
      raise warning 'L36 rollback %: % / % holds %, neither % nor %: left alone', c.id, c.game_id, c.slug, cur, c.new_v, c.old_v;
    end if;
  end loop;
  if n_missing > 0 then
    raise exception 'L36 rollback: % corrections found no row (apply L15 first)', n_missing;
  end if;
  if n_drift = 0 and n_changed not in (0, 58) then
    raise exception 'L36 rollback: % rows changed, expected 0 or 58', n_changed;
  end if;
  raise notice 'L36 rollback: % changed, % already as wanted, % left alone', n_changed, n_already, n_drift;
end;

-- The two characters with no height leave (or come back to) the pool of One Piece.
declare
  excl constant jsonb := $j$[
{"game_id":"otakudle-one-piece","series":"one-piece","slug":"nerona-imu","why":"no height stated in any allowed source"},
{"game_id":"otakudle-one-piece","series":"one-piece","slug":"shiki","why":"no height stated in any allowed source"}
]$j$;
  e record;
begin
  for e in select t.game_id, t.series, t.slug, t.why from jsonb_to_recordset(excl) as t(game_id text, series text, slug text, why text) loop
    continue when not exists (select 1 from public.dle_games where id = e.game_id);
    delete from public.dle_curation k using public.characters ch, public.groups g
    where g.id = ch.group_id and g.site_id = 'anime' and g.slug = e.series and ch.slug = e.slug
      and k.game_id = e.game_id and k.entity_id = ch.id::text and k.note like 'L36:%' and k.weight = 1;
    update public.dle_curation k set excluded = false, note = null, updated_at = now() from public.characters ch, public.groups g
    where g.id = ch.group_id and g.site_id = 'anime' and g.slug = e.series and ch.slug = e.slug
      and k.game_id = e.game_id and k.entity_id = ch.id::text and k.note like 'L36:%';
  end loop;
end;

-- The snapshot the players read (a game that has none is refreshed by its own activation).
begin
  if exists (select 1 from public.dle_entities where game_id = 'otakudle-dragon-ball') then perform public.dle_refresh_entities('otakudle-dragon-ball'); end if;
  if exists (select 1 from public.dle_entities where game_id = 'otakudle-one-piece') then perform public.dle_refresh_entities('otakudle-one-piece'); end if;
end;

notify pgrst, 'reload schema';

end $o1l36r$;
